INSERT INTO `pipeline_steps` VALUES (2, 1, 'check-code', ' alpine:latest', 'echo \"Starting code check...\"\nls -l /workspace\necho \"Code check passed.\"\ntail -f /etc/os-release', NULL, 0, '2026-01-31 18:38:56', NULL);
INSERT INTO `pipeline_steps` VALUES (3, 3, '构建', ' docker.m.daocloud.io/library/golang:1.25.7', 'echo \"开始构建...\"\nexport GO111MODULE=on\nexport GOPROXY=https://goproxy.cn,direct\nexport CGO_ENABLED=0\nexport GOOS=linux\nexport GOARCH=amd64\n\ngo mod tidy\ngo mod download\ngo build -ldflags=\"-s -w\" -o devops ./cmd/server/main.go\necho \"构建完成...\"\nls\n', NULL, 0, '2026-02-21 15:33:23', NULL);
INSERT INTO `pipeline_steps` VALUES (4, 3, '部署', 'bitnami/kubectl:latest', 'echo \"开始部署...\"\nkubectl apply -f ./k8s/\n\nkubectl rollout status deployment/devops-backend -n default --timeout=120s\necho \"部署成功...\"', '打包推送', 2, '2026-02-21 15:34:56', NULL);
INSERT INTO `pipeline_steps` VALUES (5, 9, '编译构建', 'paketobuildpacks/nodejs:latest', 'echo \"开始编译构建...\"\n#npm install \n#npm run  build:dev\necho \"构建成功...\"', NULL, 0, '2026-02-21 19:53:16', NULL);
INSERT INTO `pipeline_steps` VALUES (6, 9, '构建镜像', 'apline:latest', 'echo \"构建镜像...\"', '编译构建', 1, '2026-02-21 19:53:17', NULL);
INSERT INTO `pipeline_steps` VALUES (7, 3, '打包推送', 'gcr.m.daocloud.io/kaniko-project/executor:latest', '--skip-tls-verify\n--context=dir:///workspace\n--dockerfile=./Dockerfile\n--destination=harbor.peppa-pig.top:8443/argo-workflow/devops-backend:latest\n--cache=true\n--cache-ttl=24h', '构建', 1, '2026-02-21 23:25:21', NULL);
